import React, { useEffect, useRef, useState } from 'react';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';

// Fix pour les icônes Leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
});

const MapComponent = ({ 
  latitude = 48.8566, 
  longitude = 2.3522, 
  zoom = 13,
  markerText = "Salle",
  draggable = false,
  onPositionChange = null,
  height = "400px"
}) => {
  const mapContainerRef = useRef(null);
  const mapRef = useRef(null);
  const markerRef = useRef(null);
  const [mapKey, setMapKey] = useState(Date.now()); // Clé unique pour forcer le re-render

  // Initialiser la carte UNE SEULE FOIS
  useEffect(() => {
    if (!mapContainerRef.current || mapRef.current) return;

    console.log('Initialisation de la carte...');
    
    // Créer la carte
    mapRef.current = L.map(mapContainerRef.current, {
      center: [latitude, longitude],
      zoom: zoom,
      zoomControl: true
    });

    // Ajouter les tuiles OpenStreetMap
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '© OpenStreetMap contributors',
      maxZoom: 19,
    }).addTo(mapRef.current);

    // Créer le marqueur
    markerRef.current = L.marker([latitude, longitude], {
      draggable: draggable,
      title: markerText
    }).addTo(mapRef.current)
      .bindPopup(markerText)
      .openPopup();

    // Si draggable, ajouter l'événement
    if (draggable && onPositionChange) {
      markerRef.current.on('dragend', function(event) {
        const marker = event.target;
        const newPosition = marker.getLatLng();
        if (onPositionChange) {
          onPositionChange(newPosition.lat, newPosition.lng);
        }
      });
    }

    // Nettoyage
    return () => {
      console.log('Nettoyage de la carte...');
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
    };
  }, [mapKey]); // Dépend seulement de mapKey

  // Mettre à jour la position si les props changent
  useEffect(() => {
    if (mapRef.current && markerRef.current) {
      const newLatLng = L.latLng(latitude, longitude);
      mapRef.current.setView(newLatLng, zoom);
      markerRef.current.setLatLng(newLatLng);
    }
  }, [latitude, longitude, zoom]);

  // Forcer le re-render si la clé change
  useEffect(() => {
    setMapKey(Date.now());
  }, [latitude, longitude]);

  return (
    <div 
      key={mapKey} // Clé unique pour forcer le re-render
      ref={mapContainerRef} 
      style={{ 
        height: height, 
        width: '100%', 
        borderRadius: '8px',
        border: '1px solid #ddd'
      }}
    />
  );
};

export default MapComponent;
